#include <cctype>
#include <iostream>
#include <sstream>
#include <string>
int main() {
    const std::string text = "C++ makes systems software";
    std::istringstream input(text);
    std::size_t words = 0; std::string word;
    while (input >> word) ++words;
    std::size_t letters = 0;
    for (unsigned char ch : text) if (std::isalpha(ch)) ++letters;
    std::cout << "words=" << words << ", letters=" << letters << '\n';
}
